update public.cms_sections set data='{"eyebrow": "OUR RANGE", "heading": "Transportation Services Built Around Your Cargo", "description": "From routine road freight to petroleum, chemical and project cargo, LMI matches the vehicle, the people and the plan to what you are moving, across Pakistan.", "action": {"label": "Explore Our Services", "path": "#services"}, "image": "/services/overview/section-1-main-image.png", "imageAlt": "LMI trucks, tanker and flatbed together", "imagePlaceholder": "[Photo: LMI trucks, tanker and flatbed together]"}'::jsonb where page_id='services' and key='sectionOne';
